package com.skyward.service;
import com.skyward.api.ApiDtos.*;
import com.skyward.security.AppPrincipal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.sql.*;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.*;

@Service
public class BookingService {
 private final JdbcTemplate db;public BookingService(JdbcTemplate db){this.db=db;}
 @Transactional
 public Map<String,Object> create(AppPrincipal user,CreateBooking request){
  Map<String,Object> f=db.queryForMap("SELECT economy_capacity,business_capacity,economy_ticket_price,business_ticket_price,departure_time FROM flights WHERE flight_id=? FOR UPDATE",request.flightId());
  int econ=((Number)f.get("economy_capacity")).intValue(),biz=((Number)f.get("business_capacity")).intValue();BigDecimal econFare=(BigDecimal)f.get("economy_ticket_price"),bizFare=(BigDecimal)f.get("business_ticket_price");LocalDateTime depart=((Timestamp)f.get("departure_time")).toLocalDateTime(),now=LocalDateTime.now();if(!now.isBefore(depart))throw new IllegalArgumentException("Flight Departed — booking is closed.");if(now.isAfter(depart.minusMinutes(30)))throw new IllegalArgumentException("Booking Closed — this flight departs in less than 30 minutes.");
  Set<String> unique=new HashSet<>();BigDecimal total=BigDecimal.ZERO;
  for(PassengerInput p:request.passengers()){
   validateVerificationId(p.verificationIdType(),p.verificationIdNumber());
   String seat=p.seatNumber().trim().toUpperCase(Locale.ROOT),cabin=p.cabinClass().toUpperCase(Locale.ROOT);if(!seat.matches("[1-9][0-9]{0,2}[A-F]")||!unique.add(seat))throw new IllegalArgumentException("Choose unique, valid seat numbers.");int row=Integer.parseInt(seat.substring(0,seat.length()-1)),col=seat.charAt(seat.length()-1)-'A',ordinal=(row-1)*6+col+1;if(ordinal>econ+biz)throw new IllegalArgumentException("Seat "+seat+" is outside this flight's cabin capacity.");String expected=ordinal<=biz?"BUSINESS":"ECONOMY";if(!expected.equals(cabin))throw new IllegalArgumentException("Seat "+seat+" belongs to "+expected+" Class.");
   Integer taken=db.queryForObject("SELECT COUNT(*) FROM tickets t JOIN bookings b ON b.booking_id=t.booking_id WHERE t.flight_id=? AND TRIM(UPPER(t.seat_number))=? AND t.ticket_status='ISSUED' AND b.status IN ('PENDING','CONFIRMED')",Integer.class,request.flightId(),seat);if(taken!=null&&taken>0)throw new IllegalArgumentException("Seat "+seat+" is already taken, please choose another.");total=total.add(expected.equals("BUSINESS")?bizFare:econFare);
   if(p.name().isBlank()||p.age()<0||p.age()>120||!Set.of("Male","Female","Other").contains(p.gender()))throw new IllegalArgumentException("Check passenger name, age, and gender.");
  }
  BigDecimal bookingTotal=total;KeyHolder kh=new GeneratedKeyHolder();db.update(c->{PreparedStatement p=c.prepareStatement("INSERT INTO bookings(user_id,flight_id,status,total_amount) VALUES(?,?,'PENDING',?)",Statement.RETURN_GENERATED_KEYS);p.setLong(1,user.id());p.setLong(2,request.flightId());p.setBigDecimal(3,bookingTotal);return p;},kh);long bookingId=Objects.requireNonNull(kh.getKey()).longValue();
  for(PassengerInput p:request.passengers()){
   String idType=p.verificationIdType().trim(),idNumber=p.verificationIdNumber().trim().toUpperCase(Locale.ROOT);
   KeyHolder pk=new GeneratedKeyHolder();db.update(c->{PreparedStatement s=c.prepareStatement("INSERT INTO passengers(booking_id,name,age,gender,passport_no,verification_id_type,verification_id_number) VALUES(?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS);s.setLong(1,bookingId);s.setString(2,p.name().trim());s.setInt(3,p.age());s.setString(4,p.gender());s.setString(5,"Passport".equals(idType)?idNumber:null);s.setString(6,idType);s.setString(7,idNumber);return s;},pk);long passengerId=Objects.requireNonNull(pk.getKey()).longValue();String seat=p.seatNumber().trim().toUpperCase(Locale.ROOT),cabin=p.cabinClass().toUpperCase(Locale.ROOT);BigDecimal fare=cabin.equals("BUSINESS")?bizFare:econFare;db.update("INSERT INTO tickets(ticket_number,booking_id,flight_id,passenger_id,seat_number,cabin_class,ticket_price,ticket_status) VALUES(?,?,?,?,?,?,?,'ISSUED')","SW-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(Locale.ROOT),bookingId,request.flightId(),passengerId,seat,cabin,fare);
  }
  db.update("INSERT INTO payments(booking_id,amount,payment_method,payment_status) VALUES(?,?,'CARD','PENDING')",bookingId,bookingTotal);syncInventory(request.flightId());
  return Map.of("bookingId",bookingId,"status","PENDING","totalAmount",bookingTotal,"message","Seats reserved. Complete simulated payment to confirm.");
 }
 @Transactional public Map<String,Object> pay(long bookingId,AppPrincipal user,String method){Map<String,Object>b=db.queryForMap("SELECT flight_id,status,total_amount FROM bookings WHERE booking_id=? AND user_id=? FOR UPDATE",bookingId,user.id());if(!"PENDING".equals(b.get("status")))throw new IllegalArgumentException("This booking is no longer pending.");db.queryForObject("SELECT flight_id FROM flights WHERE flight_id=? FOR UPDATE",Long.class,b.get("flight_id"));db.update("UPDATE payments SET payment_method=?,payment_status='PAID',payment_date=CURRENT_TIMESTAMP(6) WHERE booking_id=?",method==null?"CARD":method,bookingId);db.update("UPDATE bookings SET status='CONFIRMED' WHERE booking_id=?",bookingId);return Map.of("bookingId",bookingId,"status","CONFIRMED","totalAmount",b.get("total_amount"),"message","Payment simulated; booking confirmed.");}
 public List<Map<String,Object>> myBookings(long userId){return db.queryForList("SELECT b.booking_id bookingId,b.status,b.total_amount totalAmount,b.booking_date bookingDate,f.flight_number flightNumber,f.departure_city departureCity,f.destination_city destinationCity,f.departure_time departureTime,f.arrival_time arrivalTime,(SELECT r.request_status FROM cancellation_requests r WHERE r.booking_id=b.booking_id ORDER BY r.request_id DESC LIMIT 1) cancellationStatus FROM bookings b JOIN flights f ON f.flight_id=b.flight_id WHERE b.user_id=? ORDER BY b.booking_date DESC",userId);}
 public List<Map<String,Object>> boardingPasses(long userId){return db.queryForList("SELECT t.ticket_number ticketNumber,p.name passengerName,p.age,p.gender,p.passport_no passportNumber,p.verification_id_type verificationIdType,p.verification_id_number verificationIdNumber,f.flight_number flightNumber,a.airline_name airline,f.departure_city departureCity,f.destination_city destinationCity,f.departure_time departureTime,f.arrival_time arrivalTime,t.seat_number seatNumber,t.cabin_class cabinClass,t.ticket_price ticketPrice,b.booking_id bookingId FROM tickets t JOIN bookings b ON b.booking_id=t.booking_id JOIN passengers p ON p.passenger_id=t.passenger_id JOIN flights f ON f.flight_id=t.flight_id JOIN airlines a ON a.airline_id=f.airline_id WHERE b.user_id=? AND b.status='CONFIRMED' AND t.ticket_status='ISSUED' ORDER BY f.departure_time",userId);}
 @Transactional public Map<String,Object> requestCancellation(long bookingId,AppPrincipal user){Map<String,Object>b=db.queryForMap("SELECT b.status,b.flight_id,f.departure_time FROM bookings b JOIN flights f ON f.flight_id=b.flight_id WHERE b.booking_id=? AND b.user_id=? FOR UPDATE",bookingId,user.id());if(!Set.of("PENDING","CONFIRMED").contains(b.get("status")))throw new IllegalArgumentException("Only active bookings can be cancelled.");if(!((Timestamp)b.get("departure_time")).toLocalDateTime().isAfter(LocalDateTime.now()))throw new IllegalArgumentException("A cancellation request must be submitted before departure.");Integer count=db.queryForObject("SELECT COUNT(*) FROM cancellation_requests WHERE booking_id=? AND request_status='PENDING'",Integer.class,bookingId);if(count!=null&&count>0)throw new IllegalArgumentException("A cancellation request is already pending.");db.update("INSERT INTO cancellation_requests(booking_id,user_id,request_status) VALUES(?,?,'PENDING')",bookingId,user.id());return Map.of("message","Cancellation request sent to an administrator. Seats remain reserved until approval.");}
 @Transactional public Map<String,Object> resolveCancellation(long requestId,boolean approve,long adminId,String response){Map<String,Object>r=db.queryForMap("SELECT booking_id,user_id,request_status FROM cancellation_requests WHERE request_id=? FOR UPDATE",requestId);if(!"PENDING".equals(r.get("request_status")))throw new IllegalArgumentException("This request was already reviewed.");long bookingId=((Number)r.get("booking_id")).longValue();Map<String,Object>b=db.queryForMap("SELECT b.flight_id,b.status,b.total_amount,f.flight_number,f.departure_city,f.destination_city,f.departure_time FROM bookings b JOIN flights f ON f.flight_id=b.flight_id WHERE b.booking_id=? FOR UPDATE",bookingId);String status=approve?"CANCELLED":String.valueOf(b.get("status"));if(approve){LocalDateTime now=LocalDateTime.now(),depart=((Timestamp)b.get("departure_time")).toLocalDateTime();if(!depart.isAfter(now))throw new IllegalArgumentException("This flight has departed; its cancellation request can no longer be approved.");long seconds=Duration.between(now,depart).getSeconds();double pct=seconds>=172800?100:seconds>=43200?50:seconds>=7200?30:20;BigDecimal original=(BigDecimal)b.get("total_amount"),refund=original.multiply(BigDecimal.valueOf(pct)).divide(BigDecimal.valueOf(100),2,java.math.RoundingMode.HALF_UP);db.update("INSERT INTO booking_cancellations(booking_id,user_id,flight_id,flight_number,departure_city,destination_city,departure_time,cancelled_at,seconds_before_departure,original_amount,refund_percentage,refunded_amount,refund_reason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",bookingId,r.get("user_id"),b.get("flight_id"),b.get("flight_number"),b.get("departure_city"),b.get("destination_city"),b.get("departure_time"),Timestamp.valueOf(now),seconds,original,BigDecimal.valueOf(pct),refund,refundTier(pct));db.update("UPDATE bookings SET status='CANCELLED' WHERE booking_id=?",bookingId);db.update("UPDATE tickets SET ticket_status='CANCELLED',cancelled_at=CURRENT_TIMESTAMP(6) WHERE booking_id=? AND ticket_status='ISSUED'",bookingId);db.update("UPDATE payments SET payment_status=?,refund_amount=?,refund_date=CURRENT_TIMESTAMP(6) WHERE booking_id=?",refund.compareTo(original)==0?"REFUNDED":"PARTIALLY_REFUNDED",refund,bookingId);}
  db.update("UPDATE cancellation_requests SET request_status=?,admin_response=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP(6) WHERE request_id=?",approve?"APPROVED":"REJECTED",response,adminId,requestId);if(approve)syncInventory(((Number)b.get("flight_id")).longValue());return Map.of("bookingId",bookingId,"status",status,"message",approve?"Cancellation approved; refund summary recorded.":"Cancellation request declined.");}
 @Transactional public void deleteBookingForAdmin(long bookingId){Map<String,Object>b=db.queryForMap("SELECT flight_id,status FROM bookings WHERE booking_id=? FOR UPDATE",bookingId);if("CONFIRMED".equals(b.get("status")))throw new IllegalArgumentException("Approve cancellation first so the refund is recorded before deleting this booking.");long flightId=((Number)b.get("flight_id")).longValue();db.update("DELETE FROM bookings WHERE booking_id=?",bookingId);syncInventory(flightId);}
 private void syncInventory(long flightId){Map<String,Object> f=db.queryForMap("SELECT economy_capacity,business_capacity FROM flights WHERE flight_id=?",flightId);Map<String,Object> n=db.queryForMap("SELECT COUNT(DISTINCT CASE WHEN t.cabin_class='ECONOMY' THEN TRIM(UPPER(t.seat_number)) END) eco,COUNT(DISTINCT CASE WHEN t.cabin_class='BUSINESS' THEN TRIM(UPPER(t.seat_number)) END) biz FROM tickets t JOIN bookings b ON b.booking_id=t.booking_id WHERE t.flight_id=? AND t.ticket_status='ISSUED' AND b.status IN ('PENDING','CONFIRMED')",flightId);int ec=((Number)f.get("economy_capacity")).intValue()-((Number)n.get("eco")).intValue(),bc=((Number)f.get("business_capacity")).intValue()-((Number)n.get("biz")).intValue();db.update("UPDATE flights SET economy_available_seats=?,business_available_seats=?,available_seats=? WHERE flight_id=?",ec,bc,ec+bc,flightId);}
 private void validateVerificationId(String type,String number){String value=number==null?"":number.trim().toUpperCase(Locale.ROOT);boolean valid=switch(type==null?"":type.trim()){case "PAN Card"->value.matches("[A-Z]{5}[0-9]{4}[A-Z]");case "Aadhaar Card"->value.matches("[0-9]{12}");case "Passport"->value.matches("(?:[0-9]{9}|[A-Z][0-9]{8})");default->false;};if(valid)return;String message=switch(type==null?"":type.trim()){case "PAN Card"->"Invalid PAN format. Please check your entry.";case "Aadhaar Card"->"Invalid Aadhaar format. Enter exactly 12 digits.";case "Passport"->"Invalid Passport format. Use 9 digits or 1 letter followed by 8 digits.";default->"Choose a verification ID type.";};throw new IllegalArgumentException(message);}
 private String refundTier(double pct){return pct==100?"Cancelled at least 48 hours before departure — full refund":pct==50?"Cancelled 12–48 hours before departure — 50% refund":pct==30?"Cancelled 2–12 hours before departure — 30% refund":"Cancelled less than 2 hours before departure — 20% refund";}
}
